changeSet.sql:
create or replace function reporting_sync_package_core() returns trigger as $$
begin
    if tg_op = 'DELETE' then
        update reporting_package_facts
           set source_deleted_at=coalesce(source_deleted_at, now()), updated_at=now()
         where tenant_id=old.tenant_id and package_id=old.id;
        return old;
    end if;

    insert into reporting_package_facts (
        tenant_id, package_id, business_record_id, package_type, status,
        received_at, last_observed_at, created_at, updated_at
    ) values (
        new.tenant_id, new.id, new.business_record_id, new.package_type, new.status,
        new.created_at, new.updated_at, now(), now()
    )
    on conflict (tenant_id, package_id) do update set
        business_record_id=excluded.business_record_id,
        package_type=excluded.package_type,
        status=excluded.status,
        received_at=excluded.received_at,
        last_observed_at=excluded.last_observed_at,
        source_deleted_at=null,
        updated_at=now();
    return new;
end;
$$ language plpgsql;

create or replace function reporting_sync_document_counts() returns trigger as $$
declare
    v_tenant uuid;
    v_package uuid;
begin
    if tg_op = 'DELETE' then
        v_tenant := old.tenant_id;
        v_package := old.package_id;
    else
        v_tenant := new.tenant_id;
        v_package := new.package_id;
    end if;

    update reporting_package_facts f
       set document_count=(select count(*) from documents d where d.tenant_id=v_tenant and d.package_id=v_package),
           page_count=(select coalesce(sum(d.page_count),0) from documents d where d.tenant_id=v_tenant and d.package_id=v_package),
           updated_at=now()
     where f.tenant_id=v_tenant and f.package_id=v_package;

    if tg_op = 'DELETE' then
        return old;
    end if;
    return new;
end;
$$ language plpgsql;

create or replace function reporting_sync_export_fact() returns trigger as $$
begin
    insert into reporting_package_events (tenant_id,event_id,package_id,event_type,occurred_at,created_at)
    values (new.tenant_id,new.id,new.package_id,'EXPORT_SUCCEEDED',new.exported_at,now())
    on conflict (tenant_id,event_id) do nothing;

    update reporting_package_facts f
       set first_delivered_at=case when f.first_delivered_at is null then new.exported_at else least(f.first_delivered_at,new.exported_at) end,
           last_delivered_at=case when f.last_delivered_at is null then new.exported_at else greatest(f.last_delivered_at,new.exported_at) end,
           successful_export_cycles=(select count(*) from package_export_records e where e.tenant_id=new.tenant_id and e.package_id=new.package_id),
           updated_at=now()
     where f.tenant_id=new.tenant_id and f.package_id=new.package_id;
    return new;
end;
$$ language plpgsql;

create or replace function reporting_sync_review_fact() returns trigger as $$
begin
    update reporting_package_facts f
       set reviewed_flag=true,
           first_review_created_at=case when f.first_review_created_at is null then new.created_at else least(f.first_review_created_at,new.created_at) end,
           updated_at=now()
     where f.tenant_id=new.tenant_id and f.package_id=new.package_id;
    return new;
end;
$$ language plpgsql;

create or replace function reporting_sync_audit_fact() returns trigger as $$
declare
    v_package uuid;
    v_started timestamptz;
    v_review_created timestamptz;
    v_review_started timestamptz;
begin
    if new.resource_type='DocumentPackage' and new.action='PACKAGE_PROCESSING_COMPLETED' then
        v_package := cast(new.resource_id as uuid);
        select min(a.occurred_at) into v_started
          from audit_records a
         where a.tenant_id=new.tenant_id and a.resource_type='DocumentPackage'
           and a.resource_id=new.resource_id and a.correlation_id=new.correlation_id
           and a.action='PACKAGE_PROCESSING_STARTED' and a.occurred_at<=new.occurred_at;
        if v_started is not null and new.occurred_at>=v_started then
            update reporting_package_facts f
               set active_processing_seconds=f.active_processing_seconds + extract(epoch from (new.occurred_at-v_started)),
                   updated_at=now()
             where f.tenant_id=new.tenant_id and f.package_id=v_package;
        end if;
    elsif new.resource_type='DocumentPackage' and new.action='PACKAGE_REPROCESS_REQUESTED' then
        v_package := cast(new.resource_id as uuid);
        insert into reporting_package_events (tenant_id,event_id,package_id,event_type,occurred_at,created_at)
        values (new.tenant_id,new.id,v_package,'REPROCESS_REQUESTED',new.occurred_at,now())
        on conflict (tenant_id,event_id) do nothing;
        update reporting_package_facts f
           set reprocess_count=f.reprocess_count+1,
               last_reprocessed_at=new.occurred_at,
               updated_at=now()
         where f.tenant_id=new.tenant_id and f.package_id=v_package;
    elsif new.resource_type='DocumentPackage' and new.action='PACKAGE_PURGED' then
        v_package := cast(new.resource_id as uuid);
        update reporting_package_facts f
           set package_purged_at=new.occurred_at, updated_at=now()
         where f.tenant_id=new.tenant_id and f.package_id=v_package;
    elsif new.resource_type='ReviewTask' and new.action='REVIEW_STARTED' then
        select rt.package_id, rt.created_at into v_package, v_review_created
          from review_tasks rt
         where rt.tenant_id=new.tenant_id and cast(rt.id as text)=new.resource_id;
        if v_package is not null then
            update reporting_package_facts f
               set reviewed_flag=true,
                   first_review_created_at=coalesce(f.first_review_created_at,v_review_created),
                   first_review_started_at=case when f.first_review_started_at is null then new.occurred_at else least(f.first_review_started_at,new.occurred_at) end,
                   updated_at=now()
             where f.tenant_id=new.tenant_id and f.package_id=v_package;
        end if;
    elsif new.resource_type='ReviewTask' and new.action in ('REVIEW_APPROVED','REVIEW_REJECTED') then
        select rt.package_id into v_package
          from review_tasks rt
         where rt.tenant_id=new.tenant_id and cast(rt.id as text)=new.resource_id;
        if v_package is not null then
            select min(a.occurred_at) into v_review_started
              from audit_records a
             where a.tenant_id=new.tenant_id and a.resource_type='ReviewTask'
               and a.resource_id=new.resource_id and a.action='REVIEW_STARTED'
               and a.occurred_at<=new.occurred_at;
            update reporting_package_facts f
               set reviewed_flag=true,
                   first_review_completed_at=case when f.first_review_completed_at is null then new.occurred_at else least(f.first_review_completed_at,new.occurred_at) end,
                   first_review_started_at=coalesce(f.first_review_started_at,v_review_started),
                   updated_at=now()
             where f.tenant_id=new.tenant_id and f.package_id=v_package;
        end if;
    end if;
    return new;
end;
$$ language plpgsql;

create trigger trg_reporting_package_core_upsert
    after insert or update on document_packages
    for each row execute function reporting_sync_package_core();
create trigger trg_reporting_package_core_delete
    after delete on document_packages
    for each row execute function reporting_sync_package_core();
create trigger trg_reporting_document_counts
    after insert or update or delete on documents
    for each row execute function reporting_sync_document_counts();
create trigger trg_reporting_export_fact
    after insert on package_export_records
    for each row execute function reporting_sync_export_fact();
create trigger trg_reporting_review_fact
    after insert or update on review_tasks
    for each row execute function reporting_sync_review_fact();
create trigger trg_reporting_audit_fact
    after insert on audit_records
    for each row execute function reporting_sync_audit_fact();

rollback.sql:
drop trigger if exists trg_reporting_audit_fact on audit_records;
drop trigger if exists trg_reporting_review_fact on review_tasks;
drop trigger if exists trg_reporting_export_fact on package_export_records;
drop trigger if exists trg_reporting_document_counts on documents;
drop trigger if exists trg_reporting_package_core_delete on document_packages;
drop trigger if exists trg_reporting_package_core_upsert on document_packages;
drop function if exists reporting_sync_audit_fact();
drop function if exists reporting_sync_review_fact();
drop function if exists reporting_sync_export_fact();
drop function if exists reporting_sync_document_counts();
drop function if exists reporting_sync_package_core();
